def build(src, col):
    out = src
    for entry in T:
        en, es, mn = entry[0], entry[1], entry[2]
        n = entry[3] if len(entry) > 3 else 1
        found = out.count(en)
        if found != n:
            raise SystemExit(f"[{['','','es','mn'][col+1] if col in (1,2) else col}] expected {n}, found {found}: {en[:90]!r}")
        out = out.replace(en, (es, mn)[col - 1])
    return out

if __name__ == "__main__":
    src_path, out_dir = sys.argv[1], sys.argv[2]
    src = open(src_path, encoding="utf-8").read()
    for col, lang in ((1, "es"), (2, "mn")):
        html = build(src, col)
        open(f"{out_dir}/methodology-experience.{lang}.html", "w", encoding="utf-8").write(html)
        print(lang, "written", len(html))
